import { readyApi } from './api.js';
import { contractChoiceCopyHtml, contractPassageHtml, contractResponseComplete, contractResponseControlHtml } from './interaction-runtime.js';
import { createShortsWheelGesture, normalizeWheelDelta } from './shorts-navigation.js';
import { livePrefixState, workbookRecallCue } from './workbook-assistance.js';
import { createReaderInlineGloss, readerSentenceMarkup } from './reader-inline-gloss.js?v=reader-gloss-block-1';
import { gradeLocalQuestion, gradeLocalWorkbook } from './deterministic-grading.js';

const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const SESSION_KEY='ready-student-session';
const CACHE_INDEX='ready-passage-cache-v2:';
const state={token:'',student:null,selectedStudent:null,scope:null,passages:[],passage:null,sentences:[],questionSession:null,questionFilters:null,workbookSession:null,reviewData:null,reviewCount:0};
let busyCount=0,toastTimer,readerGlossController=null;

function busy(on,label='잠시만요…'){busyCount=Math.max(0,busyCount+(on?1:-1));$('#busy').hidden=!busyCount;$('#busy span:last-child').textContent=label;}
function toast(message,ms=1900){const node=$('#toast');node.textContent=message;node.classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('on'),ms);}
function theme(next){const dark=next==='dark';document.documentElement.classList.toggle('dark',dark);document.body.classList.toggle('dark',dark);localStorage.setItem('ready-theme',next);}
async function call(op,data={},token=state.token,label='잠시만요…'){busy(true,label);try{return await readyApi(op,data,token);}finally{busy(false);}}
function record(op,data={}){readyApi(op,data,state.token).catch(()=>{});}
function clearSession(){localStorage.removeItem(SESSION_KEY);Object.assign(state,{token:'',student:null,scope:null,passages:[],passage:null,sentences:[],questionSession:null,questionFilters:null,workbookSession:null,reviewData:null,reviewCount:0});}
async function safely(job,{auth=true}={}){try{return await job();}catch(error){if(auth&&error.status===401){clearSession();await chooseStudent();}toast(error.message||'요청을 처리하지 못했습니다.',3600);return null;}}
function show(...ids){if(!ids.includes('student-reader')&&readerGlossController){readerGlossController.destroy();readerGlossController=null;}['student-home','pin-login','student-sets','student-review','student-reader','student-questions','student-workbook','student-library'].forEach(id=>$('#'+id).hidden=!ids.includes(id));document.body.classList.toggle('study-mode',ids.includes('student-reader')||ids.includes('student-questions')||ids.includes('student-workbook'));}
function updateStudentNav(){const nav=$('#student-nav');nav.hidden=!state.token;$('#logout').hidden=!state.token;const review=nav.querySelector('[data-student-route="review"]');if(review)review.innerHTML=`Review${state.reviewCount?` <span>${state.reviewCount}</span>`:''}`;}

async function chooseStudent(){const data=await safely(()=>call('list_students',{},'','학생 목록을 불러오는 중…'),{auth:false});if(!data)return;state.selectedStudent=null;show('student-home');updateStudentNav();$('#student-list').innerHTML=data.students.length?data.students.map(student=>`<button class="student-button" type="button" data-student-id="${student.id}" data-student-name="${esc(student.name)}">${esc(student.name)}</button>`).join(''):'<div class="empty">등록된 학생이 없습니다.</div>';}
function openPin(student){state.selectedStudent=student;show('pin-login');$('#pin-student-name').textContent=student.name;$('#student-pin').focus();}
async function login(form){const values=Object.fromEntries(new FormData(form)),data=await safely(()=>call('student_login',{studentId:state.selectedStudent.id,pin:values.pin,remember:values.remember==='on'},'','PIN을 확인하는 중…'),{auth:false});form.reset();$('#student-pin').blur();if(!data)return;state.token=data.session.token;state.student=data.student;if(data.session.remember)localStorage.setItem(SESSION_KEY,JSON.stringify(data.session));else localStorage.removeItem(SESSION_KEY);await loadDashboard();}
async function loadDashboard(){const data=await safely(()=>call('student_bootstrap',{},state.token,'학습 범위를 준비하는 중…'));if(!data)return;state.student=data.student;state.scope=data.scope;state.passages=data.passages;state.reviewCount=Number(data.reviewCount)||0;updateStudentNav();renderScope();}

function hasWorkbook(passage){const identity=`${passage?.title||''} ${passage?.source_label||''}`;return /민병천|NE\s*능률|박준언|YBM/i.test(identity)&&/(?:Lesson|레슨|제)\s*[12]|[12]\s*과/i.test(identity);}
function passageChoice(passage,index){const count=Number(passage.question_count)||0,workbook=hasWorkbook(passage);return `<div class="passage-row"><button class="passage-open" type="button" data-start-passage="${passage.id}"><span><strong>${esc(passage.title)}</strong><small>${passage.source_type==='TEXTBOOK'?'교과서 본문':'모의고사'} · 지문 ${index+1}</small></span><b aria-hidden="true">›</b></button><div class="passage-actions">${workbook?`<button class="passage-workbook" type="button" data-start-workbook="${passage.id}">워크북</button>`:''}<button class="passage-question" type="button" data-start-questions="${passage.id}" ${count?'':`disabled aria-label="${esc(passage.title)} 학습 완료"`}>${count?`${count}문제`:'완료'}</button></div></div>`;}
function scopePassagesHtml(){return `<div class="passage-list">${state.passages.map(passageChoice).join('')}</div>`;}
function renderScope(){state.questionSession=null;state.workbookSession=null;show('student-sets');const questionCount=state.passages.reduce((sum,passage)=>sum+(Number(passage.question_count)||0),0),content=!state.scope?'<div class="empty scope-empty"><strong>아직 배정된 시험범위가 없습니다.</strong></div>':state.passages.length?`${questionCount?`<button class="start-study" type="button" data-open-question-filter><span><strong>문제풀기</strong><small>출처와 문제유형을 고르고 Shorts로 시작합니다.</small></span><b aria-hidden="true">›</b></button>`:''}${scopePassagesHtml()}`:'<div class="empty scope-empty"><strong>아직 배정된 지문이 없습니다.</strong></div>';$('#student-sets').innerHTML=`<div class="home-head"><span>학습할 지문</span><small>${state.scope?`${esc(state.student.school)} · ${esc(state.student.grade)}`:''}</small></div><div class="home-content">${content}</div>`;}

function filterChoiceHtml(item,kind,checked=false){return `<label class="question-filter-option"><input type="${kind==='source'?'radio':'checkbox'}" name="question-${kind}" value="${esc(item.id)}" ${checked?'checked':''}><span><strong>${esc(item.label)}</strong><small>${Number(item.count)||0}문제</small></span></label>`;}
function renderQuestionFilters(){const filters=state.questionFilters;if(!filters)return renderScope();show('student-sets');$('#student-sets').innerHTML=`<div class="filter-head"><button class="back-link" type="button" data-close-question-filter>← Home</button><p class="eyebrow">READY · QUESTION SHORTS</p><h1>문제 선택</h1><p>출처 하나와 풀고 싶은 문제유형을 여러 개 선택하세요.</p></div><form id="question-filter-form" class="question-filter-form"><fieldset><legend>문제 출처</legend><div class="question-source-grid">${filterChoiceHtml({id:'all',label:'전체',count:filters.total},'source',true)}${filters.sources.map(item=>filterChoiceHtml(item,'source')).join('')}</div></fieldset><fieldset><legend>문제유형 <small>중복 선택 가능 · 선택하지 않으면 전체</small></legend><div class="question-type-grid">${filters.types.map(item=>filterChoiceHtml(item,'type')).join('')}</div></fieldset><button class="button primary question-filter-start" type="button" data-start-filtered-questions ${filters.total?'':'disabled'}>시작</button></form>`;}
async function openQuestionFilters(){if(!state.scope)return;const data=await safely(()=>call('student_question_filters',{examId:state.scope.id},state.token,'문제 종류를 확인하는 중…'));if(!data)return;state.questionFilters=data;renderQuestionFilters();}
async function openFilteredQuestions(){if(!state.scope||!state.questionFilters)return;const source=$('input[name="question-source"]:checked')?.value||'all',taxonomies=[...document.querySelectorAll('input[name="question-type"]:checked')].map(input=>input.value),providers=source==='all'?[]:[source];const data=await safely(()=>call('student_question_queue',{examId:state.scope.id,providers,taxonomies},state.token,'선택한 문제를 준비하는 중…'));if(!data)return;if(!data.items?.length){toast('선택한 조건에 풀 수 있는 새 문제가 없습니다.');return;}startQuestionSession(data.items,'filtered');}

function workbookCurrent(){const session=state.workbookSession,stage=session?.data.stages[session.stageIndex];return {session,stage,item:stage?.items[session.itemIndex]};}
function workbookValues(session,item){return session.responses[item.key]||Array(item.slotCount).fill('');}
function workbookSlotState(result,index){return result?(result.slotResults?.[index]?'correct':'wrong'):'';}
function workbookAssistanceState(session,item){session.assistance??={};return session.assistance[item.key]??={hintCount:0,usedFullAnswerHint:false,hintReceipt:'',hints:{},live:{},requestSequence:{}};}
async function ensureWorkbookAssistance(session,item){if(!item?.assistance?.mode||item.assistance.mode==='recall_local'||Array.isArray(item.assistance.slots))return true;const data=await safely(()=>readyApi('workbook_assistance',{examId:state.scope.id,passageId:session.passageId,itemKey:item.key},state.token));if(!data?.assistance)return false;item.assistance=data.assistance;return true;}
function workbookBlankHtml(item,values,result,session){const assistance=workbookAssistanceState(session,item),recall=item.assistance?.mode==='recall_local',live=item.assistance?.mode==='prefix_typing';let slot=0;return String(item.prompt||'').split(/_{5,}/).map((part,index,all)=>{const copy=esc(part);if(index===all.length-1)return copy;const value=values[slot]||'',expected=result?.answers?.[slot]||'',status=workbookSlotState(result,slot),hint=item.hints?.[slot],measure=String(value||hint||expected||'답').length,liveState=assistance.live?.[slot],input=`<span class="workbook-blank ${status}${recall?' recall-slot':''}${live&&liveState?.valid===false?' live-mismatch':''}" style="--workbook-slot-ch:${Math.min(24,Math.max(4,measure))}"><input type="text" data-workbook-slot="${slot}" ${recall?`data-workbook-recall="${esc(item.assistance.recallMode)}"`:''} ${live?'data-workbook-live-prefix="true"':''} value="${esc(value)}" placeholder="${esc(hint||'')}" aria-label="빈칸 ${slot+1}${hint?` (${esc(hint)})`:''}" ${result?'disabled':''} autocomplete="off" autocapitalize="off" spellcheck="false">${live&&liveState?.valid===false?`<small class="workbook-live-copy"><span>${esc(value.slice(0,liveState.mismatchIndex))}</span><b>${esc(value.slice(liveState.mismatchIndex))}</b></small>`:''}${assistance.hints?.[slot]?`<small class="workbook-slot-hint">힌트: ${esc(assistance.hints[slot])}</small>`:''}${result&&status==='wrong'?`<small class="workbook-answer">정답: ${esc(expected)}</small>`:''}</span>`;slot+=1;return copy+input;}).join('');}
function workbookChoiceHtml(item,values,result){return esc(item.prompt).replace(/⟦CHOICE:(\d+)⟧/g,(_all,indexText)=>{const index=Number(indexText),status=workbookSlotState(result,index),options=item.groups?.[index]||[];return `<span class="workbook-choice-group ${status}" role="group" aria-label="둘 중 하나 선택 ${index+1}">${options.map((option,optionIndex)=>`<button type="button" data-workbook-choice-group="${index}" data-workbook-choice-value="${esc(option)}" class="workbook-choice${values[index]===option?' selected':''}" aria-pressed="${values[index]===option}" ${result?'disabled':''}><span>${esc(option)}</span>${values[index]===option?'<b aria-hidden="true">✓</b>':''}</button>${optionIndex===0?'<i class="workbook-choice-or" aria-hidden="true">또는</i>':''}`).join('')}${result&&status==='wrong'?`<small>정답: ${esc(result.answers[index])}</small>`:''}</span>`;});}
function workbookCorrectionHtml(item,values,result){return `<div class="workbook-task-passage" lang="en">${esc(item.prompt)}</div><div class="workbook-correction-list">${Array.from({length:item.pairCount},(_,pair)=>{const wrongIndex=pair*2,correctIndex=wrongIndex+1,status=result?(result.slotResults?.[wrongIndex]&&result.slotResults?.[correctIndex]?'correct':'wrong'):'';return `<div class="workbook-correction-row ${status}"><span>${pair+1}</span><label>어색한 표현<input type="text" data-workbook-slot="${wrongIndex}" value="${esc(values[wrongIndex]||'')}" ${result?'disabled':''} autocomplete="off" autocapitalize="off" spellcheck="false"></label><b aria-hidden="true">→</b><label>바르게 고치기<input type="text" data-workbook-slot="${correctIndex}" value="${esc(values[correctIndex]||'')}" ${result?'disabled':''} autocomplete="off" autocapitalize="off" spellcheck="false"></label>${result&&status==='wrong'?`<small>${esc(result.answers[wrongIndex])} → ${esc(result.answers[correctIndex])}</small>`:''}</div>`;}).join('')}</div>`;}
function workbookOrderSelections(session,item){session.orderSelections??={};return session.orderSelections[item.key]??=Array.from({length:item.groups?.length||0},()=>[]);}
function workbookOrderGroupHtml(item,index,result,session){const selections=workbookOrderSelections(session,item),group=item.groups?.[index]||[],chosen=selections[index]||[],chosenSet=new Set(chosen),status=workbookSlotState(result,index);return `<span class="workbook-order-group ${status}" data-workbook-order-group="${index}"><span class="workbook-order-built" aria-label="배열한 문장">${chosen.length?chosen.map(chipIndex=>`<button type="button" data-workbook-order-remove="${index}:${chipIndex}" ${result?'disabled':''}>${esc(group[chipIndex])}</button>`).join(' '):''}</span><span class="workbook-order-bank" aria-label="선택할 단어">${group.map((word,chipIndex)=>`<span class="workbook-order-bank-slot ${chosenSet.has(chipIndex)?'used':''}"><button type="button" data-workbook-order-add="${index}:${chipIndex}" ${chosenSet.has(chipIndex)?'aria-hidden="true" tabindex="-1"':''} ${result?'disabled':''}>${esc(word)}</button></span>`).join('')}</span>${result&&status==='wrong'?`<small>정답: ${esc(result.answers[index])}</small>`:''}</span>`;}
function workbookOrderHtml(item,values,result,session){return esc(item.prompt).replace(/⟦ORDER:(\d+)⟧/g,(_all,indexText)=>workbookOrderGroupHtml(item,Number(indexText),result,session));}
function stabilizeWorkbookOrderGeometry(root=document){const groups=root.matches?.('.workbook-order-group')?[root]:[...(root.querySelectorAll?.('.workbook-order-group')||[])];groups.forEach(group=>{const bank=group.querySelector('.workbook-order-bank'),built=group.querySelector('.workbook-order-built');if(bank&&built){const style=getComputedStyle(built),chrome=Number.parseFloat(style.paddingTop)+Number.parseFloat(style.paddingBottom)+Number.parseFloat(style.borderTopWidth)+Number.parseFloat(style.borderBottomWidth);group.style.setProperty('--workbook-order-stable-height',`${Math.ceil(bank.getBoundingClientRect().height+chrome)}px`);}});}
function refreshWorkbookOrderGroup(index){const {session,item}=workbookCurrent(),current=document.querySelector(`[data-workbook-order-group="${index}"]`);if(!session||!item||!current)return renderWorkbook();const template=document.createElement('template');template.innerHTML=workbookOrderGroupHtml(item,index,session.results[item.key],session).trim();const next=template.content.firstElementChild,stableHeight=current.style.getPropertyValue('--workbook-order-stable-height');if(stableHeight)next.style.setProperty('--workbook-order-stable-height',stableHeight);current.replaceWith(next);stabilizeWorkbookOrderGeometry(next);const values=workbookValues(session,item),ready=values.length===item.slotCount&&values.every(value=>String(value).trim());const submit=document.querySelector('[data-submit-workbook]');if(submit)submit.disabled=!ready;}
function workbookTaskHtml(item,values,result,session){if(item.kind==='translation_ai')return `<label class="workbook-translation"><span>나의 해석</span><textarea rows="3" data-workbook-slot="0" ${result?'disabled':''} placeholder="우리말 해석을 입력하세요">${esc(values[0]||'')}</textarea></label>`;if(item.kind==='choice_groups')return `<div class="workbook-prompt choice-task" lang="en">${workbookChoiceHtml(item,values,result)}</div>`;if(item.kind==='correction_pairs')return workbookCorrectionHtml(item,values,result);if(item.kind==='reorder_groups')return `<div class="workbook-prompt order-task" lang="en">${workbookOrderHtml(item,values,result,session)}</div>`;const assistance=workbookAssistanceState(session,item),hintControls=Number(item.stage)===9&&!result?`<div class="workbook-hint-actions"><button class="button quiet small" type="button" data-workbook-hint ${assistance.hintCount>=2?'disabled':''}>${assistance.hintCount?'힌트 한 번 더':'힌트 보기'}</button><small>${assistance.usedFullAnswerHint?'이 문제는 복습에 추가됐어요. 계속 완성해 보세요.':assistance.hintCount===1?'첫 단어 힌트를 사용했습니다. 한 번 더 누르면 전체 답을 봅니다.':''}</small></div>`:'';return `<div class="workbook-prompt" lang="${item.stage===2?'ko':'en'}">${workbookBlankHtml(item,values,result,session)}</div>${hintControls}`;}
function workbookTabsHtml(session){return session.data.stages.map((stage,index)=>`<button type="button" data-workbook-stage="${index}" class="${index===session.stageIndex?'active':''}" ${stage.locked?'disabled aria-disabled="true"':''}><span>${stage.stage}단계${stage.locked?' · 준비 중':''}</span><b>${stage.locked?'잠김':`${stage.completed}/${stage.total}`}</b></button>`).join('');}
function workbookStageChoicesHtml(session){return session.data.stages.map((stage,index)=>{const available=!stage.locked&&stage.items.length,complete=available&&stage.total>0&&stage.completed>=stage.total;return `<button class="workbook-stage-option${complete?' complete':''}" type="button" data-workbook-stage="${index}" ${available?'':`disabled aria-disabled="true"`}><span class="workbook-stage-copy"><strong>${stage.stage}단계</strong><small>${esc(stage.title||stage.instruction||'워크북 학습')}</small></span><span class="workbook-stage-state"><small>${available?`${stage.completed} / ${stage.total}`:'준비 중'}</small><b aria-hidden="true">${available?'→':'—'}</b></span></button>`;}).join('');}
function renderWorkbookStages(){const session=state.workbookSession;if(!session)return renderScope();show('student-workbook');document.body.classList.remove('study-mode');$('#student-workbook').innerHTML=`<div class="workbook-stage-picker"><header class="filter-head workbook-picker-head"><button class="back-link" type="button" data-exit-workbook>← Home</button><p class="eyebrow">READY · WORKBOOK</p><h1>${esc(session.data.title)}</h1><p>학습할 단계를 선택하세요. 이어서 풀 단계에는 현재 진도가 표시됩니다.</p></header><section class="workbook-stage-list" aria-labelledby="workbook-stage-title"><div class="workbook-stage-list-head"><h2 id="workbook-stage-title">단계 선택</h2><small>${session.data.stages.filter(stage=>!stage.locked&&stage.items.length).length}개 단계</small></div>${workbookStageChoicesHtml(session)}</section></div>`;}
function workbookFeedbackHtml(item,result){if(!result)return'';if(item.kind==='translation_ai'&&Number.isFinite(result.aiScore)){const lines=(result.aiFeedbackLines?.length?result.aiFeedbackLines:[result.aiFeedback]).filter(Boolean).slice(0,3);return `<div class="workbook-feedback ${result.correct?'correct':'wrong'}"><strong>${result.aiScore}점 · ${result.correct?'통과':'다시 해보기'}</strong><span class="workbook-feedback-copy">${lines.map(line=>`<span>${esc(line)}</span>`).join('')}</span></div>`;}if(result.completedAfterHint)return `<div class="workbook-feedback wrong"><strong>끝까지 완성했습니다.</strong><span>전체 답 힌트를 사용해 이번 기록은 복습에 추가됐어요. 다음에는 힌트 없이 다시 풀어 보세요.</span></div>`;return `<div class="workbook-feedback ${result.correct?'correct':'wrong'}"><strong>${result.correct?'정답입니다.':'표시된 부분만 고쳐 보세요.'}</strong><span>${esc(result.aiFeedback||(result.correct?'Enter를 누르거나 다음 문장으로 넘어가세요.':'Review에 자동 저장했습니다. 맞은 부분은 유지됩니다.'))}</span></div>`;}
function workbookResponseReady(session,item){if(item.kind==='reorder_groups'){const selections=workbookOrderSelections(session,item);return (item.groups||[]).length===item.slotCount&&(item.groups||[]).every((group,index)=>(selections[index]||[]).length===group.length);}const values=workbookValues(session,item);return values.length===item.slotCount&&values.every(value=>String(value).trim());}
function workbookResultActionHtml(result,nextLabel){if(!result)return'';return `<div class="workbook-actions">${!result.correct?'<button class="button primary" type="button" data-workbook-retry>틀린 부분 다시 풀기</button>':`<button class="button primary" type="button" data-workbook-next>${nextLabel}</button>`}</div>`;}
function workbookAiStatusHtml(session,item){if(session.aiPending?.[item.key])return '<div class="local-ai-status" role="status"><strong>AI가 해석을 확인하고 있어요…</strong><span>작성한 답안은 그대로 유지됩니다.</span></div>';const error=session.aiErrors?.[item.key];return error?`<div class="local-ai-status error" role="status"><strong>${esc(error)}</strong><span>연결을 확인한 뒤 다시 채점해 주세요.</span></div>`:'';}
function renderWorkbook(){const {session,stage,item}=workbookCurrent();if(!session||!stage||!item)return renderWorkbookStages();const values=workbookValues(session,item),result=session.results[item.key],lastItem=session.itemIndex===stage.items.length-1,lastStage=session.stageIndex===session.data.stages.length-1,nextLabel=lastItem?(lastStage?'학습 목록':'다음 단계'):'다음 문제';show('student-workbook');document.body.classList.add('study-mode');$('#student-workbook').innerHTML=`<button class="study-back" type="button" data-workbook-stages aria-label="워크북 단계 선택으로"><span aria-hidden="true">‹</span></button><div class="workbook-study-layout"><header class="workbook-study-head workbook-study-toolbar"><span class="workbook-state"><b>${session.itemIndex+1} / ${stage.total}</b><button class="question-bookmark ${item.bookmarked?'active':''}" type="button" data-toggle-workbook-bookmark aria-pressed="${!!item.bookmarked}" aria-label="${item.bookmarked?'Review에서 제거':'Review에 저장'}">${bookmarkIcon(item.bookmarked)}</button></span></header><section class="workbook-card workbook-focus-card">${item.source?`<blockquote lang="${item.kind==='translation_ai'?'en':item.kind==='blank_input'?'en':'ko'}">${esc(item.source)}</blockquote>`:''}${item.wordBank?.length?`<div class="workbook-word-bank"><small>사용할 말</small>${item.wordBank.map(word=>`<span>${esc(word)}</span>`).join('')}</div>`:''}${workbookTaskHtml(item,values,result,session)}${workbookAiStatusHtml(session,item)}${workbookFeedbackHtml(item,result)}${workbookResultActionHtml(result,nextLabel)}</section></div>`;requestAnimationFrame(()=>stabilizeWorkbookOrderGeometry($('#student-workbook')));}
async function openWorkbook(passageId,targetItemKey=''){
  if(!state.scope)return;
  const data=await safely(()=>call('student_workbook',{examId:state.scope.id,passageId},state.token,'워크북을 준비하는 중…'));if(!data)return;
  const available=data.stages.map((stage,index)=>({...stage,index})).filter(stage=>!stage.locked&&stage.items.length);let next=targetItemKey?available.find(stage=>stage.items.some(item=>item.key===targetItemKey)):null;next=next||available.find(stage=>stage.completed<stage.total)||available[0];
  if(!next){toast('현재 풀 수 있는 워크북 단계가 없습니다.');return;}
  const stageIndex=next.index,stage=data.stages[stageIndex],targetIndex=targetItemKey?stage.items.findIndex(item=>item.key===targetItemKey):-1,itemIndex=targetIndex>=0?targetIndex:Math.max(0,stage.items.findIndex(item=>!item.completed));
  state.workbookSession={data,passageId,stageIndex,itemIndex,responses:{},results:{},orderSelections:{},assistance:{},aiPending:{},aiErrors:{},persistenceSequence:{},focusedSlot:0};
  if(!targetItemKey)return renderWorkbookStages();
  if(await ensureWorkbookAssistance(state.workbookSession,stage.items[itemIndex]))renderWorkbook();
}
function updateWorkbookSlot(index,value){const {session,item}=workbookCurrent();if(!session||!item||session.results[item.key])return;const values=[...(session.responses[item.key]||Array(item.slotCount).fill(''))];values[index]=value;session.responses[item.key]=values;const submit=$('[data-submit-workbook]');if(submit)submit.disabled=!values.every(item=>String(item).trim());}
function flashRecallWrong(input){input.classList.add('recall-wrong');const snapshot=input.value;setTimeout(()=>{if(input.value===snapshot)input.value='';input.classList.remove('recall-wrong');input.focus();},220);}
function handleWorkbookRecallInput(input){
  const {session,item}=workbookCurrent();
  if(!session||!item||session.results[item.key]||input.dataset.unlocking==='true')return;
  const index=Number(input.dataset.workbookSlot),mode=input.dataset.workbookRecall,cue=workbookRecallCue(input.value,mode),raw=String(input.value||'').trim();
  if(!raw)return;
  const answer=item.grading?.answers?.[index],expected=workbookRecallCue(answer,mode);
  if(!cue){if(input.dataset.composing!=='true')flashRecallWrong(input);return;}
  if(cue!==expected){if(input.dataset.composing!=='true')flashRecallWrong(input);return;}
  input.dataset.unlocking='true';updateWorkbookSlot(index,answer);input.value=answer;input.classList.add('recall-complete');input.readOnly=true;
  const next=document.querySelector(`[data-workbook-slot="${index+1}"]`);if(next)next.focus();
  const values=workbookValues(session,item);if(values.length===item.slotCount&&values.every(value=>String(value).trim()))submitWorkbook();
}
async function handleWorkbookLiveInput(input){const {session,item}=workbookCurrent();if(!session||!item||session.results[item.key])return;const index=Number(input.dataset.workbookSlot),value=input.value,assistance=workbookAssistanceState(session,item),sequence=(assistance.requestSequence[index]||0)+1;assistance.requestSequence[index]=sequence;updateWorkbookSlot(index,value);const live=await livePrefixState(value,item.assistance?.slots?.[index]);if(assistance.requestSequence[index]!==sequence)return;assistance.live[index]=live;const wrapper=input.closest('.workbook-blank');wrapper?.classList.toggle('live-mismatch',live.valid===false);let copy=wrapper?.querySelector('.workbook-live-copy');if(live.valid===false){if(!copy){copy=document.createElement('small');copy.className='workbook-live-copy';wrapper.append(copy);}copy.innerHTML=`<span>${esc(value.slice(0,live.mismatchIndex))}</span><b>${esc(value.slice(live.mismatchIndex))}</b>`;}else copy?.remove();}
async function requestWorkbookHint(){const {session,item}=workbookCurrent();if(!session||!item||Number(item.stage)!==9||session.results[item.key])return;const assistance=workbookAssistanceState(session,item),values=workbookValues(session,item),slot=Math.min(item.slotCount-1,Math.max(0,Number(session.focusedSlot??values.findIndex(value=>!String(value).trim()))));const data=await safely(()=>call('workbook_hint',{examId:state.scope.id,passageId:session.passageId,itemKey:item.key,slot,hintReceipt:assistance.hintReceipt||''},state.token,'힌트를 준비하는 중…'));if(!data)return;assistance.hintCount=data.hintCount;assistance.usedFullAnswerHint=data.usedFullAnswerHint===true;assistance.hintReceipt=data.hintReceipt;assistance.hints[slot]=data.fragment;renderWorkbook();requestAnimationFrame(()=>document.querySelector(`[data-workbook-slot="${slot}"]`)?.focus());}
function queueWorkbookAutoSubmit(){const {session,item}=workbookCurrent();if(!session||!item||session.results[item.key]||session.submitting||!workbookResponseReady(session,item))return;const itemKey=item.key;queueMicrotask(()=>{const current=workbookCurrent();if(current.session===session&&current.item?.key===itemKey&&!session.results[itemKey]&&!session.submitting&&workbookResponseReady(session,current.item))submitWorkbook();});}
function chooseWorkbookOption(group,value){updateWorkbookSlot(group,value);renderWorkbook();queueWorkbookAutoSubmit();}
function changeWorkbookOrder(group,chipIndex,remove=false){const {session,item}=workbookCurrent();if(!session||!item||session.results[item.key])return;const selections=workbookOrderSelections(session,item),current=[...(selections[group]||[])],position=current.indexOf(chipIndex);if(remove&&position>=0)current.splice(position,1);else if(!remove&&position<0)current.push(chipIndex);selections[group]=current;const words=(item.groups?.[group]||[]);updateWorkbookSlot(group,current.map(index=>words[index]).join(' '));refreshWorkbookOrderGroup(group);queueWorkbookAutoSubmit();}
function applyWorkbookOutcome(session,item,result){session.results[item.key]=result;item.completed=result.correct;item.lastResult=result.correct;if(result.correct){const stage=session.data.stages[session.stageIndex];stage.completed=stage.items.filter(candidate=>candidate.completed).length;}}
function workbookServerResult(data){return {correct:data.correct,answers:data.answers,slotResults:data.slotResults,aiFeedback:data.aiFeedback||'',aiFeedbackLines:data.aiFeedbackLines||[],aiScore:typeof data.aiScore==='number'?data.aiScore:null,gradingPolicy:data.gradingPolicy||null,hintCount:Number(data.hintCount)||0,usedFullAnswerHint:data.usedFullAnswerHint===true,completedAfterHint:data.completedAfterHint===true};}
async function persistWorkbookAttempt(session,item,body,sequence){const data=await safely(()=>readyApi('submit_workbook_attempt',body,state.token));if(!data)return;item.bookmarked=data.bookmarked;state.reviewCount=Number(data.reviewCount)||0;updateStudentNav();const current=session.results[item.key];if(current?.persistenceSequence===sequence){applyWorkbookOutcome(session,item,{...workbookServerResult(data),persistenceSequence:sequence});renderWorkbook();}}
async function submitWorkbook(){const {session,item}=workbookCurrent();if(!session||!item||session.results[item.key]||session.submitting)return;const responses=[...(session.responses[item.key]||[])];if(responses.length!==item.slotCount||responses.some(value=>!String(value).trim()))return;const assistance=workbookAssistanceState(session,item),body={examId:state.scope.id,passageId:session.passageId,itemKey:item.key,responses,hintReceipt:assistance.hintReceipt||''};
  if(item.grading?.mode==='deterministic'){
    const grade=gradeLocalWorkbook(item.grading,responses,{usedFullAnswerHint:assistance.usedFullAnswerHint});if(!grade.valid)return;
    const sequence=(session.persistenceSequence[item.key]||0)+1;session.persistenceSequence[item.key]=sequence;
    applyWorkbookOutcome(session,item,{...grade,hintCount:assistance.hintCount,usedFullAnswerHint:assistance.usedFullAnswerHint,persistenceSequence:sequence});renderWorkbook();
    persistWorkbookAttempt(session,item,body,sequence);return;
  }
  if(navigator.onLine===false){session.aiErrors[item.key]='AI 채점은 인터넷 연결이 필요해요.';renderWorkbook();return;}
  session.submitting=true;session.aiPending[item.key]=true;delete session.aiErrors[item.key];renderWorkbook();
  const data=await safely(()=>readyApi('submit_workbook_attempt',body,state.token));session.submitting=false;delete session.aiPending[item.key];
  if(!data){session.aiErrors[item.key]=navigator.onLine===false?'AI 채점은 인터넷 연결이 필요해요.':'AI 채점을 완료하지 못했습니다.';renderWorkbook();return;}
  applyWorkbookOutcome(session,item,workbookServerResult(data));item.bookmarked=data.bookmarked;state.reviewCount=Number(data.reviewCount)||0;updateStudentNav();renderWorkbook();
}
async function toggleWorkbookBookmark(){const {session,item}=workbookCurrent();if(!session||!item)return;const next=!item.bookmarked,data=await safely(()=>call('set_workbook_bookmark',{examId:state.scope.id,passageId:session.passageId,itemKey:item.key,bookmarked:next},state.token,next?'Review에 저장하는 중…':'Review에서 제거하는 중…'));if(!data)return;item.bookmarked=data.bookmarked;state.reviewCount=Number(data.reviewCount)||0;updateStudentNav();renderWorkbook();}
function retryWorkbook(){const {session,item}=workbookCurrent();if(!session||!item)return;const result=session.results[item.key],previous=session.responses[item.key]||Array(item.slotCount).fill('');let next=result?.completedAfterHint?Array(item.slotCount).fill(''):previous.map((value,index)=>result?.slotResults?.[index]?value:'');if(item.kind==='correction_pairs')for(let pair=0;pair<item.pairCount;pair+=1){const left=pair*2,right=left+1;if(!result?.slotResults?.[left]||!result?.slotResults?.[right])next[left]=next[right]='';}if(item.kind==='reorder_groups'){const selections=workbookOrderSelections(session,item);result?.slotResults?.forEach((correct,index)=>{if(!correct)selections[index]=[];});}session.responses[item.key]=next;session.assistance[item.key]={hintCount:0,usedFullAnswerHint:false,hintReceipt:'',hints:{},live:{},requestSequence:{}};delete session.results[item.key];renderWorkbook();requestAnimationFrame(()=>document.querySelector('[data-workbook-slot][value=""]')?.focus());}
async function moveWorkbook(delta){const {session,stage}=workbookCurrent();if(!session||!stage)return;const next=session.itemIndex+delta;if(next>=0&&next<stage.items.length){session.itemIndex=next;if(await ensureWorkbookAssistance(session,stage.items[next]))renderWorkbook();return;}if(next>=stage.items.length){const nextStage=session.data.stages.findIndex((candidate,index)=>index>session.stageIndex&&!candidate.locked&&candidate.items.length);if(nextStage>=0){session.stageIndex=nextStage;session.itemIndex=0;if(await ensureWorkbookAssistance(session,session.data.stages[nextStage].items[0]))renderWorkbook();return;}return renderScope();}}
async function setWorkbookStage(index){const session=state.workbookSession,stage=session?.data.stages[index];if(!session||!stage||stage.locked)return;session.stageIndex=index;session.itemIndex=Math.max(0,stage.items.findIndex(item=>!item.completed));if(await ensureWorkbookAssistance(session,stage.items[session.itemIndex]))renderWorkbook();}

function cleanDisplayText(value){return String(value||'').replace(/^\s*(?:[※]\s*)?다음\s*(?:글|대화)(?:을|를)\s*읽고\s*(?:다음\s*)?물음에\s*답하시오\s*[.!?]?\s*/u,'').replace(/\s+/g,' ').trim();}
function plainPassage(){return state.sentences.map(sentence=>esc(cleanDisplayText(sentence.text))).filter(Boolean).join(' ');}
function readerUnits(){const text=state.sentences.map(sentence=>cleanDisplayText(sentence.text)).filter(Boolean).join(' ');if(!text)return [];try{return [...new Intl.Segmenter('en',{granularity:'sentence'}).segment(text)].map(item=>item.segment.trim()).filter(Boolean);}catch{return text.split(/(?<=[.!?])\s+(?=[A-Z“"'])/).filter(Boolean);}}
function readerParagraphs(units){const paragraphs=[];let current=[];for(const unit of units){const length=current.join(' ').length;if(current.length&&length+unit.length>430){paragraphs.push(current.join(' '));current=[];}current.push(unit);}if(current.length)paragraphs.push(current.join(' '));return paragraphs;}
function readerGlossEnabled(){return window.READY_CONFIG?.READER_INLINE_GLOSS_ENABLED===true;}
function readerGlossParagraphs(sentences){const paragraphs=[];let current=[];for(const sentence of sentences){const length=current.reduce((sum,item)=>sum+item.text.length+1,0);if(current.length&&length+sentence.text.length>430){paragraphs.push(current);current=[];}current.push(sentence);}if(current.length)paragraphs.push(current);return paragraphs;}
function readerGlossSentenceHtml(sentence){return `<span class="reader-inline-sentence" data-reader-sentence-id="${esc(sentence.id)}">${readerSentenceMarkup(sentence)}</span>`;}
function renderReader(){
  readerGlossController?.destroy();readerGlossController=null;
  if(!readerGlossEnabled()){const units=readerUnits(),lead=units.shift()||'',paragraphs=readerParagraphs(units);show('student-reader');$('#student-reader').innerHTML=`<button class="study-back" type="button" data-exit-study aria-label="학습 목록으로"><span aria-hidden="true">‹</span></button><div class="reader-shell reader-document"><p class="eyebrow">TEXTBOOK · READER</p><h1>${esc(state.passage.title)}</h1>${lead?`<p class="reader-lede">${esc(lead)}</p>`:''}<article class="reader-prose">${paragraphs.length?paragraphs.map(paragraph=>`<p>${esc(paragraph)}</p>`).join(''):`<p>${plainPassage()}</p>`}</article></div>`;return;}
  const sentences=state.sentences.map(sentence=>({id:sentence.id,text:String(sentence.text||'').trim()})).filter(sentence=>sentence.text),lead=sentences.shift(),paragraphs=readerGlossParagraphs(sentences),root=$('#student-reader');show('student-reader');root.dataset.readerPassageId=state.passage.id;root.innerHTML=`<button class="study-back" type="button" data-exit-study aria-label="학습 목록으로"><span aria-hidden="true">‹</span></button><div class="reader-shell reader-document"><p class="eyebrow">TEXTBOOK · READER</p><h1>${esc(state.passage.title)}</h1>${lead?`<p class="reader-lede">${readerGlossSentenceHtml(lead)}</p>`:''}<article class="reader-prose">${paragraphs.length?paragraphs.map(paragraph=>`<p>${paragraph.map(readerGlossSentenceHtml).join(' ')}</p>`).join(''):'<p></p>'}</article><p class="reader-inline-notice" data-reader-gloss-notice hidden></p><span class="sr-only" data-reader-gloss-live aria-live="polite"></span></div>`;
  readerGlossController=createReaderInlineGloss({root,passage:state.passage,sentences:[...(lead?[lead]:[]),...sentences],request:data=>readyApi('reader_inline_gloss',{examId:state.scope.id,...data},state.token)});
}
function cacheIndexKey(passageId){return `${CACHE_INDEX}${state.student?.id}:${passageId}`;}
function cachedPassage(passageId){try{const pointer=JSON.parse(localStorage.getItem(cacheIndexKey(passageId))||'null');return pointer?.key?JSON.parse(localStorage.getItem(pointer.key)||'null'):null;}catch{return null;}}
function cachePassage(data){try{const revision=[data.passage.id,data.passage.updated_at||'current'].join(':'),key=`ready-passage-cache-v2:${state.student.id}:${revision}`;localStorage.setItem(key,JSON.stringify(data));localStorage.setItem(cacheIndexKey(data.passage.id),JSON.stringify({key,revision}));}catch{/* disposable acceleration only */}}
function applyPassage(data){Object.assign(state,{passage:data.passage,sentences:data.sentences||[]});}
async function openPassageStudy(passageId){if(!state.scope)return;state.questionSession=null;const cached=cachedPassage(passageId);if(cached){applyPassage(cached);renderReader();}const data=await safely(()=>cached?readyApi('student_passage',{examId:state.scope.id,passageId},state.token):call('student_passage',{examId:state.scope.id,passageId},state.token,'지문을 준비하는 중…'));if(!data)return;applyPassage(data);renderReader();cachePassage(data);localStorage.setItem(`ready-last-passage:${state.student.id}:${state.scope.id}`,passageId);}

function questionPassageHtml(question,result,selected,inlineSelected=[]){return contractPassageHtml(question.interactionContract,{escape:esc,result,selected,inlineSelected});}
function choiceCopyHtml(question,_text,index){return contractChoiceCopyHtml(question.interactionContract,index,esc);}
function questionChoiceHtml(question,text,index,result,selected,markState){const mark=['①','②','③','④','⑤','⑥','⑦','⑧'][index],correct=!!result&&(result.answer?.includes(index)||(result.correct&&selected)),wrong=!!result&&!correct&&selected,state=!result&&(markState==='candidate'||markState==='eliminated')?` ${markState}`:'';return `<div class="question-choice${state} ${selected?'selected':''} ${correct?'correct':''} ${wrong?'wrong':''}" role="${question.multiSelect?'checkbox':'radio'}" aria-checked="${selected}" tabindex="${result?'-1':'0'}" data-question-choice="${index}" data-choice-mark="${esc(markState||'neutral')}"><span class="question-choice-mark">${mark}</span><span class="question-choice-copy">${choiceCopyHtml(question,text,index)}</span></div>`;}
function writingGuideHtml(guide){if(!guide)return '';const task=guide.taskText?`<section class="writing-target"><strong>${esc(guide.taskLabel||'작성할 내용')}</strong><p>${esc(guide.taskText)}</p></section>`:'',conditions=(guide.conditions||[]).length?`<section class="writing-conditions"><strong>조건</strong><ul>${guide.conditions.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></section>`:'',bank=(guide.wordBank||[]).length?`<section class="writing-bank"><strong>사용할 말</strong><div>${guide.wordBank.map(item=>`<span>${esc(item)}</span>`).join('')}</div></section>`:'';return `${task}${conditions}${bank}`;}
function writtenSlotsHtml(contract,values,result){return `<div class="written-slot-list">${contract.response.slots.map((slot,index)=>`<label><span>${esc(slot.label)}</span>${contractResponseControlHtml(contract,index,{escape:esc,value:values[index]||'',disabled:!!result})}</label>`).join('')}</div>`;}
function contractBlankHtml(slot,index){const count=Math.max(1,Number(slot?.wordCount)||1);return `<span class="contract-blank" role="img" aria-label="${esc(slot?.label||index+1)}번 빈칸, ${count}단어">${Array.from({length:count},()=>'<i aria-hidden="true"></i>').join('')}</span>`;}
function contractTemplateHtml(response){return (response?.template||[]).map(item=>item.kind==='text'?esc(item.text):contractBlankHtml(response.slots[item.slotIndex],item.slotIndex)).join('');}
function questionSummaryHtml(question){const response=question.interactionContract?.response;return response?.layout==='summary'?contractTemplateHtml(response):esc(question.summaryText);}
function responseArea(question,result,selected,choiceMarks=[]){
  if(question.responseType!=='written')return `${result?'':'<p class="choice-swipe-hint">왼쪽으로 밀면 제외 · 오른쪽으로 밀면 정답 후보</p>'}<section class="question-answer-area${question.interaction==='choice_matrix'?' choice-matrix':''}" aria-label="선택지">${question.choices.map((choice,index)=>questionChoiceHtml(question,choice,index,result,selected.includes(index),choiceMarks[index])).join('')}</section>`;
  const values=Array.isArray(selected)?selected:[],contract=question.interactionContract,response=contract.response,slots=response.slots,guide=question.writingGuide,targets=guide?.targets||[];
  if(response.layout==='correction')return `<section class="written-workspace correction">${writingGuideHtml(guide)}${targets.map((target,index)=>`<label><span class="correction-source"><b>${esc(target.label)}</b><em>${esc(target.text)}</em></span><i aria-hidden="true">→</i><span class="correction-answer"><small>${esc(slots[index].label)}</small>${contractResponseControlHtml(contract,index,{escape:esc,value:values[index]||'',disabled:!!result})}</span></label>`).join('')}</section>`;
  if(response.layout==='multi_correction')return `<section class="written-workspace multi-correction">${writingGuideHtml(guide)}<div class="correction-reference">${targets.map(target=>`<span><b>${esc(target.label)}</b>${esc(target.text)}</span>`).join('')}</div>${writtenSlotsHtml(contract,values,result)}</section>`;
  if(response.layout==='sentence_cloze')return `<section class="written-workspace sentence-cloze">${writingGuideHtml(guide)}<div class="cloze-frame" lang="en">${contractTemplateHtml(response)}</div><div class="written-slot-list cloze-slot-list">${slots.map((slot,index)=>`<label><span>${esc(slot.label)}</span>${contractResponseControlHtml(contract,index,{escape:esc,value:values[index]||'',disabled:!!result})}</label>`).join('')}</div></section>`;
  if(['summary','sentence_parts','short_answers'].includes(response.layout))return `<section class="written-workspace ${response.layout.replace('_','-')}">${writingGuideHtml(guide)}${writtenSlotsHtml(contract,values,result)}</section>`;
  const slot=slots[0];return `<section class="written-workspace ${esc(response.layout)}">${writingGuideHtml(guide)}<label class="sentence-answer"><span>${esc(slot.label)}</span>${contractResponseControlHtml(contract,0,{escape:esc,value:values[0]||'',disabled:!!result})}</label></section>`;
}
function hasResponse(question,selected,inlineSelected=[]){if(question.interaction==='inline_options'){const groups=question.interactionContract?.passage?.segments?.filter(segment=>segment.kind==='inline_options')||[];return inlineSelected.length===groups.length&&inlineSelected.every(Number.isInteger);}return question.responseType==='written'?contractResponseComplete(question.interactionContract,selected):Array.isArray(selected)&&selected.length>0;}
function resultFeedbackHtml(question,result){if(!result)return '';const explanation=String(result.explanation||'').trim(),action=explanation?`<div class="feedback-actions"><button type="button" data-toggle-explanation>${result.showExplanation?'해설 닫기':'해설 보기'}</button></div>`:'',revealed=result.showExplanation&&explanation?`<p class="explanation-reveal">${esc(explanation)}</p>`:'',ai=result.aiFeedback?`<p class="ai-grade-feedback"><strong>AI 채점</strong>${esc(result.aiFeedback)}</p>`:'';if(result.correct)return `<div class="question-feedback correct"><strong>정답입니다.</strong><span>북마크하면 Review에서 다시 볼 수 있습니다.</span>${ai}${action}${revealed}</div>`;return `<div class="question-feedback wrong"><strong>오답으로 기록했습니다.</strong><span>Review에 자동으로 저장했습니다.</span>${ai}${action}${revealed}</div>`;}
function questionOutcome(question,result){if(result)return result.correct?'correct':'wrong';return question.lastResult===true?'correct':question.lastResult===false?'wrong':'';}
