function questionAiStatusHtml(session,question,ready){if(session.aiPending[question.id])return '<div class="local-ai-status" role="status"><strong>AI가 답안을 확인하고 있어요…</strong><span>작성한 답안은 그대로 유지됩니다.</span></div>';const error=session.aiErrors[question.id];if(error)return `<div class="local-ai-status error" role="status"><strong>${esc(error)}</strong><span>답안을 유지했어요. 연결 후 다시 제출해 주세요.</span></div>`;return `<button class="button primary question-submit" type="button" data-submit-question ${ready?'':'disabled'}>제출</button>`;}
function renderQuestion(){const session=state.questionSession;if(!session)return renderScope();const item=session.items[session.index],question=item.question||item,result=session.results[question.id],selected=session.responses[question.id]||[],inlineSelected=session.inlineSelections[question.id]||[],choiceMarks=session.choiceMarks[question.id]||[],phase=result?'submitted':'solving',displayPrompt=question.writingGuide?.title||question.prompt,extras=new Set(question.renderSpec?.extras||[]),showStimulus=question.stimulus&&extras.has('stimulus'),showSummary=question.summaryText&&extras.has('summary'),showPassage=question.interactionContract?.passage?.visible,outcome=questionOutcome(question,result);show('student-questions');$('#student-questions').innerHTML=`<button class="study-back" type="button" data-exit-questions aria-label="Home으로"><span aria-hidden="true">‹</span></button><div class="question-layout" data-question-phase="${phase}"><div class="reader-shell"><div class="question-topline"><span class="question-progress">${question.source?.passageNo?`${question.source.passageNo}번 · `:''}${session.index+1} / ${session.items.length}</span><div class="question-state"><span class="question-result-dot ${outcome}" role="img" aria-label="${outcome==='correct'?'맞힌 문제':outcome==='wrong'?'틀린 문제':'아직 풀지 않은 문제'}"></span><button class="question-bookmark ${question.bookmarked?'active':''}" type="button" data-toggle-bookmark aria-pressed="${!!question.bookmarked}" aria-label="${question.bookmarked?'Review에서 제거':'Review에 저장'}">${bookmarkIcon(question.bookmarked)}</button></div></div><p class="eyebrow">PASSAGE · ${esc((question.renderer||question.family||'standard').toUpperCase())}</p>${showStimulus?`<section class="question-stimulus"><strong>주어진 문장</strong>${esc(question.stimulus)}</section>`:''}${showPassage?`<article class="reading-passage question-passage">${questionPassageHtml(question,result,selected,inlineSelected)}</article>`:''}<h1 class="question-prompt">${esc(displayPrompt)}</h1>${showSummary?`<section class="question-summary">${questionSummaryHtml(question)}</section>`:''}${responseArea(question,result,selected,choiceMarks)}<div class="question-submit-row">${result?resultFeedbackHtml(question,result):questionAiStatusHtml(session,question,hasResponse(question,selected,inlineSelected))}</div><div class="shorts-cue"><button class="button quiet small" type="button" data-question-prev aria-label="이전 문제" ${session.index===0?'disabled':''}>↑</button><small>${session.index===session.items.length-1?'마지막 문제':'위아래로 넘겨 이동'}</small><button class="button quiet small" type="button" data-question-next aria-label="다음 문제" ${session.index===session.items.length-1?'disabled':''}>↓</button></div></div></div>`;}
function startQuestionSession(items,mode='passage'){state.questionSession={items,index:0,responses:{},inlineSelections:{},choiceMarks:{},results:{},aiPending:{},aiErrors:{},persistenceSequence:{},startedAt:performance.now(),mode};renderQuestion();}
async function openQuestions(passageId){if(!state.scope)return;const data=await safely(()=>call('student_questions',{examId:state.scope.id,passageId},state.token,'문제를 준비하는 중…'));if(!data)return;if(!data.questions?.length){toast('이 지문의 새 문제를 모두 풀었습니다.');return loadDashboard();}applyPassage(data);startQuestionSession(data.questions.map(question=>({...question,passageText:question.passageText||plainPassage()})));}
function renderReview(){const data=state.reviewData;if(!data)return renderScope();const questions=data.items||[],workbooks=data.workbookItems||[];show('student-review');$('#student-review').innerHTML=`<div class="review-head"><span>Review</span><small>틀린 것과 직접 북마크한 학습</small></div><div class="review-sections">${questions.length?`<section class="review-group"><div><p class="eyebrow">QUESTION</p><h2>시험 문제 ${questions.length}개</h2></div><button class="button primary" type="button" data-start-review-questions>다시 풀기</button></section>`:''}${workbooks.length?`<section class="review-group workbook-review-group"><div><p class="eyebrow">WORKBOOK</p><h2>본문 체화 ${workbooks.length}개</h2></div><div class="review-workbook-list">${workbooks.map(item=>`<button type="button" data-review-workbook-passage="${item.passageId}" data-review-workbook-item="${item.itemKey}"><span><strong>${esc(item.title)} · ${item.number}</strong><small>${esc(item.passageTitle)} · ${item.lastResult===false?'오답':'북마크'}</small></span><b>›</b></button>`).join('')}</div></section>`:''}${!questions.length&&!workbooks.length?'<div class="empty"><strong>Review에 저장된 학습이 없습니다.</strong></div>':''}</div>`;}
async function openReview(){if(!state.scope)return;const data=await safely(()=>call('student_review_questions',{examId:state.scope.id},state.token,'Review를 준비하는 중…'));if(!data)return;state.reviewData=data;state.reviewCount=(data.items?.length||0)+(data.workbookItems?.length||0);updateStudentNav();renderReview();}
function selectInlineOption(groupIndex,optionIndex){const session=state.questionSession,item=session?.items[session.index],question=item?.question||item;if(!question||session.results[question.id]||question.interaction!=='inline_options')return;const current=[...(session.inlineSelections[question.id]||[])];current[groupIndex]=optionIndex;session.inlineSelections[question.id]=current;renderQuestion();}
function updateWrittenSlot(index,value){const session=state.questionSession,item=session?.items[session.index],question=item?.question||item;if(!question||session.results[question.id])return;const slots=question.responseSlots?.length||1,current=[...(session.responses[question.id]||Array(slots).fill(''))];current[index]=value;session.responses[question.id]=current;const submit=$('[data-submit-question]');if(submit)submit.disabled=!hasResponse(question,current);}
function questionServerResult(data){return {correct:data.correct,answer:data.answer,explanation:data.explanation,aiFeedback:data.aiFeedback||'',showExplanation:false};}
async function persistQuestionAttempt(session,question,body,sequence){const data=await safely(()=>readyApi('submit_attempt',body,state.token));if(!data)return;question.lastResult=data.correct;if(data.bookmarked)question.bookmarked=true;state.reviewCount=Number(data.reviewCount)||0;updateStudentNav();const current=session.results[question.id];if(current?.persistenceSequence===sequence){session.results[question.id]={...questionServerResult(data),persistenceSequence:sequence};renderQuestion();}}
async function submitCurrentQuestion(){const session=state.questionSession,item=session?.items[session.index],question=item?.question||item,response=question?[...(session.responses[question.id]||[])]:[],inlineSelected=question?[...(session.inlineSelections[question.id]||[])]:[];if(!question||!hasResponse(question,response,inlineSelected)||session.results[question.id]||session.aiPending[question.id])return;const body={examId:state.scope.id,questionId:question.id,elapsedMs:Math.round(performance.now()-session.startedAt)};if(question.responseType==='written')body.responses=response;else if(question.interaction==='inline_options')body.inlineSelected=inlineSelected;else body.selected=response;
  const local=gradeLocalQuestion(question.grading,body);if(!local.valid)return;
  if(!local.needsServer){const sequence=(session.persistenceSequence[question.id]||0)+1;session.persistenceSequence[question.id]=sequence;session.results[question.id]={correct:local.correct,answer:local.correct?null:local.answer,explanation:question.explanation||'',aiFeedback:'',showExplanation:false,persistenceSequence:sequence};question.lastResult=local.correct;renderQuestion();persistQuestionAttempt(session,question,body,sequence);return;}
  if(navigator.onLine===false){session.aiErrors[question.id]='AI 채점은 인터넷 연결이 필요해요.';renderQuestion();return;}
  session.aiPending[question.id]=true;delete session.aiErrors[question.id];renderQuestion();const data=await safely(()=>readyApi('submit_attempt',body,state.token));delete session.aiPending[question.id];
  if(!data){session.aiErrors[question.id]=navigator.onLine===false?'AI 채점은 인터넷 연결이 필요해요.':'AI 채점을 완료하지 못했습니다.';renderQuestion();return;}
  question.lastResult=data.correct;if(data.bookmarked)question.bookmarked=true;state.reviewCount=Number(data.reviewCount)||0;updateStudentNav();session.results[question.id]=questionServerResult(data);renderQuestion();
}
function toggleExplanation(){const session=state.questionSession,item=session?.items[session.index],question=item?.question||item,result=question&&session.results[question.id];if(!result||!result.explanation)return;result.showExplanation=!result.showExplanation;renderQuestion();}
function moveQuestion(delta){const session=state.questionSession;if(!session)return;const next=session.index+delta;if(next>=session.items.length||next<0)return;session.index=next;session.startedAt=performance.now();renderQuestion();requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'auto'}));}
async function toggleQuestionBookmark(){const session=state.questionSession,item=session?.items[session.index],question=item?.question||item;if(!question)return;const next=!question.bookmarked,data=await safely(()=>call('set_question_bookmark',{examId:state.scope.id,questionId:question.id,bookmarked:next},state.token,next?'Review에 저장하는 중…':'Review에서 제거하는 중…'));if(!data)return;question.bookmarked=data.bookmarked;state.reviewCount=Number(data.reviewCount)||0;updateStudentNav();renderQuestion();}
function exitQuestions(){state.questionSession=null;return loadDashboard();}
async function logout(){if(state.token)record('logout');clearSession();await chooseStudent();}

// Selection state has one source of truth: a ruled-out choice can never remain
// in the response that is submitted.
function selectQuestionChoice(index){const session=state.questionSession,item=session?.items[session.index],question=item?.question||item;if(!question||session.results[question.id]||question.responseType==='written')return;const current=session.responses[question.id]||[],marks=[...(session.choiceMarks[question.id]||[])];marks[index]='neutral';session.choiceMarks[question.id]=marks;session.responses[question.id]=question.multiSelect?(current.includes(index)?current.filter(value=>value!==index):[...current,index].sort((a,b)=>a-b)):[index];renderQuestion();}
function markQuestionChoice(index,direction){const session=state.questionSession,item=session?.items[session.index],question=item?.question||item;if(!question||session.results[question.id]||question.responseType==='written')return;const marks=[...(session.choiceMarks[question.id]||[])],current=marks[index]||'neutral';marks[index]=direction==='left'?(current==='eliminated'?'neutral':'eliminated'):(current==='candidate'?'neutral':'candidate');session.choiceMarks[question.id]=marks;if(marks[index]==='eliminated')session.responses[question.id]=(session.responses[question.id]||[]).filter(value=>value!==index);renderQuestion();}

let choiceSwipe=null,choiceClickBlockedUntil=0;
function finishChoiceSwipe(event,cancelled=false){if(!choiceSwipe||event.pointerId!==choiceSwipe.pointerId)return;const swipe=choiceSwipe;choiceSwipe=null;swipe.node.classList.remove('swiping');swipe.node.style.removeProperty('--choice-drag');swipe.node.removeAttribute('data-swipe-direction');const dx=event.clientX-swipe.startX,dy=event.clientY-swipe.startY;if(!cancelled&&Math.abs(dx)>=46&&Math.abs(dx)>Math.abs(dy)){choiceClickBlockedUntil=Date.now()+450;markQuestionChoice(Number(swipe.node.dataset.questionChoice),dx<0?'left':'right');}}
document.addEventListener('pointerdown',event=>{const choice=event.target.closest?.('[data-question-choice]');if(!choice||event.button>0||choice.closest('[data-question-phase="submitted"]'))return;choiceSwipe={node:choice,pointerId:event.pointerId,startX:event.clientX,startY:event.clientY};choice.setPointerCapture?.(event.pointerId);choice.classList.add('swiping');});
document.addEventListener('pointermove',event=>{if(!choiceSwipe||event.pointerId!==choiceSwipe.pointerId)return;const dx=event.clientX-choiceSwipe.startX,dy=event.clientY-choiceSwipe.startY;if(Math.abs(dx)<=Math.abs(dy)||Math.abs(dx)<6)return;event.preventDefault();const distance=Math.max(-76,Math.min(76,dx));choiceSwipe.node.style.setProperty('--choice-drag',`${distance}px`);choiceSwipe.node.dataset.swipeDirection=distance<0?'left':'right';},{passive:false});
document.addEventListener('pointerup',event=>finishChoiceSwipe(event));
document.addEventListener('pointercancel',event=>finishChoiceSwipe(event,true));
let workbookBackSwipe=null;
function finishWorkbookBackSwipe(event,cancelled=false){if(!workbookBackSwipe||event.pointerId!==workbookBackSwipe.pointerId)return;const swipe=workbookBackSwipe;workbookBackSwipe=null;const dx=event.clientX-swipe.startX,dy=event.clientY-swipe.startY,backGesture=dx<=-64||(swipe.fromLeftEdge&&dx>=64);if(!cancelled&&backGesture&&Math.abs(dx)>Math.abs(dy)*1.2)moveWorkbook(-1);}
document.addEventListener('pointerdown',event=>{if(event.pointerType==='mouse'||!state.workbookSession||$('#student-workbook').hidden||event.target.closest?.('input,textarea,select,button,[contenteditable="true"]'))return;const root=$('#student-workbook');workbookBackSwipe={pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,fromLeftEdge:event.clientX<=36};root.setPointerCapture?.(event.pointerId);});
document.addEventListener('pointerup',event=>finishWorkbookBackSwipe(event));
document.addEventListener('pointercancel',event=>finishWorkbookBackSwipe(event,true));
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-workbook-hint]');if(!button)return;event.stopImmediatePropagation();requestWorkbookHint();},true);
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-workbook-stages]');if(!button)return;event.stopImmediatePropagation();renderWorkbookStages();},true);
document.addEventListener('focusin',event=>{if(event.target.matches?.('[data-workbook-slot]')&&state.workbookSession)state.workbookSession.focusedSlot=Number(event.target.dataset.workbookSlot)||0;});
document.addEventListener('compositionstart',event=>{if(event.target.matches?.('[data-workbook-recall]'))event.target.dataset.composing='true';});
document.addEventListener('compositionend',event=>{if(!event.target.matches?.('[data-workbook-recall]'))return;event.target.dataset.composing='false';handleWorkbookRecallInput(event.target);});
document.addEventListener('input',event=>{const input=event.target;if(input.matches?.('[data-workbook-recall]')){event.stopImmediatePropagation();handleWorkbookRecallInput(input);return;}if(input.matches?.('[data-workbook-live-prefix]')){event.stopImmediatePropagation();handleWorkbookLiveInput(input);}},true);
document.addEventListener('click',event=>{const button=event.target.closest('button'),choice=event.target.closest('[data-question-choice]');if(button?.dataset.inlineGroup!==undefined)return selectInlineOption(Number(button.dataset.inlineGroup),Number(button.dataset.inlineOption));if(choice){if(Date.now()<choiceClickBlockedUntil){event.preventDefault();return;}return selectQuestionChoice(Number(choice.dataset.questionChoice));}if(button?.hasAttribute('data-question-prev'))return moveQuestion(-1);if(button?.hasAttribute('data-question-next'))return moveQuestion(1);if(button?.hasAttribute('data-toggle-bookmark'))return toggleQuestionBookmark();if(button?.hasAttribute('data-toggle-workbook-bookmark'))return toggleWorkbookBookmark();if(button?.dataset.workbookChoiceGroup!==undefined)return chooseWorkbookOption(Number(button.dataset.workbookChoiceGroup),button.dataset.workbookChoiceValue||'');if(button?.dataset.workbookOrderAdd){const [group,chip]=button.dataset.workbookOrderAdd.split(':').map(Number);return changeWorkbookOrder(group,chip);}if(button?.dataset.workbookOrderRemove){const [group,chip]=button.dataset.workbookOrderRemove.split(':').map(Number);return changeWorkbookOrder(group,chip,true);}if(button?.id==='theme-toggle')return theme(document.body.classList.contains('dark')?'light':'dark');if(button?.id==='logout')return logout();if(button?.dataset.studentId)return openPin({id:button.dataset.studentId,name:button.dataset.studentName});if(button?.hasAttribute('data-back-students'))return chooseStudent();if(button?.hasAttribute('data-open-question-filter'))return openQuestionFilters();if(button?.hasAttribute('data-close-question-filter'))return renderScope();if(button?.hasAttribute('data-start-filtered-questions'))return openFilteredQuestions();if(button?.hasAttribute('data-start-review-questions'))return startQuestionSession(state.reviewData?.items||[],'review');if(button?.dataset.reviewWorkbookPassage)return openWorkbook(button.dataset.reviewWorkbookPassage,button.dataset.reviewWorkbookItem||'');if(button?.dataset.startWorkbook)return openWorkbook(button.dataset.startWorkbook);if(button?.dataset.startPassage)return openPassageStudy(button.dataset.startPassage);if(button?.dataset.startQuestions)return openQuestions(button.dataset.startQuestions);if(button?.hasAttribute('data-open-review')||button?.dataset.studentRoute==='review')return openReview();if(button?.hasAttribute('data-exit-workbook'))return renderScope();if(button?.hasAttribute('data-submit-workbook'))return submitWorkbook();if(button?.hasAttribute('data-workbook-retry'))return retryWorkbook();if(button?.hasAttribute('data-workbook-next'))return moveWorkbook(1);if(button?.hasAttribute('data-workbook-prev'))return moveWorkbook(-1);if(button?.dataset.workbookStage!==undefined)return setWorkbookStage(Number(button.dataset.workbookStage));if(button?.hasAttribute('data-exit-questions')||(button?.dataset.studentRoute==='passages'&&state.questionSession))return exitQuestions();if(button?.hasAttribute('data-exit-study')||button?.dataset.studentRoute==='passages')return renderScope();if(button?.hasAttribute('data-submit-question'))return submitCurrentQuestion();if(button?.hasAttribute('data-toggle-explanation'))return toggleExplanation();});
document.addEventListener('input',event=>{if(event.target.matches('[data-written-slot]'))updateWrittenSlot(Number(event.target.dataset.writtenSlot),event.target.value);if(event.target.matches('[data-workbook-slot]'))updateWorkbookSlot(Number(event.target.dataset.workbookSlot),event.target.value);});
document.addEventListener('keydown',event=>{if(event.key!=='Enter'||event.isComposing||event.keyCode===229||!state.workbookSession||$('#student-workbook').hidden)return;const {session,item}=workbookCurrent(),result=session?.results?.[item?.key],slot=event.target.closest?.('[data-workbook-slot]');if(!result&&!slot)return;if(slot?.matches('textarea')&&event.shiftKey)return;event.preventDefault();if(!result){if(workbookResponseReady(session,item))return submitWorkbook();const next=[...document.querySelectorAll('[data-workbook-slot]')].find(input=>!String(input.value||'').trim()&&!input.disabled&&!input.readOnly);next?.focus();return;}if(result.correct)return moveWorkbook(1);return retryWorkbook();});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='pin-form')return login(event.target);});
document.addEventListener('keydown',event=>{const choice=event.target.closest?.('[data-question-choice]');if(choice&&(event.key==='Enter'||event.key===' ')){event.preventDefault();selectQuestionChoice(Number(choice.dataset.questionChoice));}});

const shortsWheel=createShortsWheelGesture();
let shortsTouch=null;
function questionScreenActive(){return !!state.questionSession&&!$('#student-questions').hidden;}
function formControl(target){return target?.closest?.('input,textarea,select,button,[contenteditable="true"]');}
function atQuestionBoundary(direction){const scroller=document.scrollingElement||document.documentElement,top=Math.max(0,Number(scroller.scrollTop)||0,Number(window.scrollY)||0),total=Math.max(scroller.scrollHeight||0,document.documentElement.scrollHeight||0,document.body?.scrollHeight||0),max=Math.max(0,total-window.innerHeight);return direction<0?top<=4:top>=max-4;}
window.addEventListener('wheel',event=>{if(!questionScreenActive()||formControl(event.target))return;const delta=normalizeWheelDelta(event,window.innerHeight),direction=delta>0?1:-1,navigation=shortsWheel.push({delta,atBoundary:atQuestionBoundary(direction)});if(!navigation)return;if(event.cancelable)event.preventDefault();moveQuestion(navigation);},{passive:false});
function beginShortsTouch(identifier,y,target){if(!questionScreenActive()||target?.closest?.('input,textarea,select,[contenteditable="true"]'))return;shortsTouch={identifier,startY:y,lastY:y,atTop:atQuestionBoundary(-1),atBottom:atQuestionBoundary(1)};}
function endShortsTouch(identifier,y){if(!shortsTouch||shortsTouch.identifier!==identifier)return;const gesture=shortsTouch;shortsTouch=null;const dy=y-gesture.startY;if(Math.abs(dy)<64)return;if(dy<0&&gesture.atBottom)return moveQuestion(1);if(dy>0&&gesture.atTop)return moveQuestion(-1);}
const touchNavigation='ontouchstart'in window||(navigator.maxTouchPoints||0)>0;
if(touchNavigation){
  document.addEventListener('touchstart',event=>{if(event.touches.length!==1)return;const touch=event.touches[0];beginShortsTouch(touch.identifier,touch.clientY,event.target);},{passive:true});
  document.addEventListener('touchmove',event=>{if(!shortsTouch||event.touches.length!==1)return;const touch=event.touches[0],dy=touch.clientY-shortsTouch.startY;shortsTouch.lastY=touch.clientY;if(Math.abs(dy)>18&&((dy<0&&shortsTouch.atBottom)||(dy>0&&shortsTouch.atTop))&&event.cancelable)event.preventDefault();},{passive:false});
  document.addEventListener('touchend',event=>{const touch=Array.from(event.changedTouches).find(item=>item.identifier===shortsTouch?.identifier);if(touch)endShortsTouch(touch.identifier,touch.clientY);},{passive:true});
  document.addEventListener('touchcancel',()=>{shortsTouch=null;},{passive:true});
}else{
  document.addEventListener('pointerdown',event=>{if(event.pointerType==='mouse')return;beginShortsTouch(event.pointerId,event.clientY,event.target);});
  document.addEventListener('pointerup',event=>endShortsTouch(event.pointerId,event.clientY));
  document.addEventListener('pointercancel',()=>{shortsTouch=null;});
}
document.addEventListener('keydown',event=>{if(!questionScreenActive()||formControl(event.target)||!['ArrowUp','ArrowDown','PageUp','PageDown'].includes(event.key))return;event.preventDefault();moveQuestion(['ArrowDown','PageDown'].includes(event.key)?1:-1);});

theme(localStorage.getItem('ready-theme')||(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'));
try{const previous=JSON.parse(localStorage.getItem(SESSION_KEY)||'null');if(previous?.token){state.token=previous.token;loadDashboard();}else chooseStudent();}catch{chooseStudent();}
